/**
 * Joins supabase/migrations/*.sql (in order) into supabase/setup.sql: one file to paste into the Supabase SQL Editor.
 * Run `npm run db:bundle` after editing a migration. A test fails if setup.sql is out of date.
 */
import fs from "node:fs";
import path from "node:path";

const dir = "supabase/migrations";
const files = fs
  .readdirSync(dir)
  .filter((f) => f.endsWith(".sql"))
  .sort();
const body = files
  .map(
    (f) =>
      `-- ============================================================\n-- ${f}\n-- ============================================================\n${fs.readFileSync(path.join(dir, f), "utf8").trimEnd()}\n`,
  )
  .join("\n");
const header = `-- SellSharp database setup (generated by scripts/build-sql-bundle.mjs — do not edit; edit supabase/migrations instead).\n-- Paste this whole file into Supabase → SQL Editor → New query → Run. Safe to run more than once.\n\n`;
fs.writeFileSync("supabase/setup.sql", header + body);
console.log(`supabase/setup.sql written from ${files.length} migrations`);
